/**
 * A sign-in, sign-up or password reset card: heading, one sentence, the fields of the mode, a submit button,
 * optional alternative sign-in buttons and a link to the other mode. Axes: mode (signin, signup, reset), layout
 * (card, plain), social (none, show).
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Button } from "../primitives/button/button";
import { Group } from "../primitives/group/group";
import { Link } from "../primitives/link/link";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Separator } from "../primitives/separator/separator";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { AuthForm } from "../components/auth-form";
import { cn, tpl } from "../utils";
import type { AuthLabels } from "./auth-card.types";

export type AuthCardProps = {
  id: string;
  title: string;
  text: string;
  submit: string;
  switchText: string;
  switchLink: string;
  switchHref?: string;
  labels: AuthLabels;
  mode?: "signin" | "signup" | "reset" | "magic";
  layout?: "card" | "plain";
  social?: "none" | "show" | "first";
  level?: 1 | 2;
  landmarkLabel?: string;
};

export function AuthCard({
  id,
  title,
  text,
  submit,
  switchText,
  switchLink,
  switchHref,
  labels,
  mode = "signin",
  layout = "card",
  social = "none",
  level = 2,
  landmarkLabel,
}: AuthCardProps) {
  return (
    <Block
      tag="section"
      className={cn(
        "flex w-full flex-col gap-6",
        (((layout as string) === "card") ? "rounded bg-card p-6 inset-ring inset-ring-border" : "")
      )}
      aria-labelledby={(landmarkLabel ? undefined : tpl("{0}-title", id))}
      data-testid="auth-card"
      data-mode={mode}
      aria-label={landmarkLabel}
    >
      <Stack gap="2">
        <Title as={level} size="2xl" weight="bold" id={tpl("{0}-title", id)}>
          {title}
        </Title>
        <Text size="sm" className="text-muted-foreground">
          {text}
        </Text>
      </Stack>
      {(((social as string) === "first") && ((social as string) !== "none") && ((mode as string) !== "reset") && ((mode as string) !== "magic")) ? (
        <Stack gap="4" data-testid="social">
          <Group gap="4" align="center">
            <Separator className="flex-1" />
            <Text size="xs" className="text-muted-foreground">
              {labels.divider}
            </Text>
            <Separator className="flex-1" />
          </Group>
          <Button variant="outline" size="default" type="button" className="w-full">
            <LucideIcon name="key-round" size={16} />
            {labels.passkey}
          </Button>
          <Button variant="outline" size="default" type="button" className="w-full">
            <LucideIcon name="mail" size={16} />
            {labels.magic}
          </Button>
        </Stack>
      ) : null}
      <AuthForm id={id} mode={mode} labels={labels} submit={submit} />
      {(((social as string) !== "first") && ((social as string) !== "none") && ((mode as string) !== "reset") && ((mode as string) !== "magic")) ? (
        <Stack gap="4" data-testid="social">
          <Group gap="4" align="center">
            <Separator className="flex-1" />
            <Text size="xs" className="text-muted-foreground">
              {labels.divider}
            </Text>
            <Separator className="flex-1" />
          </Group>
          <Button variant="outline" size="default" type="button" className="w-full">
            <LucideIcon name="key-round" size={16} />
            {labels.passkey}
          </Button>
          <Button variant="outline" size="default" type="button" className="w-full">
            <LucideIcon name="mail" size={16} />
            {labels.magic}
          </Button>
        </Stack>
      ) : null}
      <Text size="sm" className="text-center text-muted-foreground">
        {switchText}
        {" "}
        <Link href={switchHref} variant="default" data-testid="switch">
          {switchLink}
        </Link>
      </Text>
    </Block>
  );
}

